# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift


def shift(worker, span="09:00-12:30"):
    return Shift(worker, "mon", parse_span(span))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_totals(self):
        lines = timesheet_lines([
            shift("ann", "09:00-10:00"),
            shift("bob"),
            shift("ann", "13:00-14:00"),
            shift("bob", "13:00-14:00")
        ])
        self.assertEqual(lines, [
            "bob: 2 shifts, 4.5 h",
            "ann: 2 shifts, 2.0 h"
        ])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([shift("ann"), shift("  ")])
